class 线程安全GUI:
    """提供线程安全的GUI操作方法"""

    def __init__(self, 主窗口):
        self.主窗口 = 主窗口
        self.队列 = queue.Queue()
        self.检查队列()

    def 检查队列(self):
        """定期检查并执行队列中的GUI操作"""
        try:
            while True:
                任务 = self.队列.get_nowait()
                try:
                    任务()
                except Exception as e:
                    logger.error(f"GUI任务执行失败: {e}")
        except queue.Empty:
            pass
        self.主窗口.after(100, self.检查队列)

    def 安全调用(self, 函数, *参数, **关键字参数):
        """安全地在主线程中调用GUI函数"""
        def 包装函数():
            try:
                函数(*参数, **关键字参数)
            except Exception as e:
                logger.error(f"GUI调用失败: {e}")

        self.队列.put(包装函数)

