        """添加文件夹"""
        try:
            文件夹路径 = filedialog.askdirectory(title="选择文件夹")
            if 文件夹路径:
                文件数量 = 0
                for 扩展名 in ["*.json", "*.txt", "*.yaml", "*.yml"]:
                    for 文件路径 in Path(文件夹路径).rglob(扩展名):
